select is((select count(*)::integer from pg_class where oid in ('public.b2c_certificate_results'::regclass,'public.b2c_certificate_history'::regclass,'public.b2c_certificate_requests'::regclass) and relrowsecurity),3,'Certificate tables have RLS');
select ok(not has_function_privilege('anon','public.write_b2c_certificate_result(text,jsonb)','EXECUTE'),'Anon cannot write certificate results');
select set_config('request.jwt.claims','{"sub":"17500000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select set_config('test.cert',jsonb_build_object('request_id','17500000-0000-4000-8000-000000000020','id',null,'expected_updated_at',null,'student_id','17500000-0000-4000-8000-000000000010','certificate_type','IELTS','level','Academic','score','6.5','exam_date','2026-10-17','marketing_allowed',false,'marketing_note','','notes','PRIVATE-NOTE')::text,true);
