select throws_ok($$select public.write_b2c_certificate_result('save',current_setting('test.cert')::jsonb||'{"student_id":"17500000-0000-4000-8000-000000000099"}')$$,'22023',null,'Missing student rejected');
select lives_ok($$select public.write_b2c_certificate_result('save',current_setting('test.cert')::jsonb)$$,'Manager saves result');
select lives_ok($$select public.write_b2c_certificate_result('save',current_setting('test.cert')::jsonb)$$,'Exact retry succeeds');
select is((select count(*)::integer from public.b2c_certificate_results where student_id='17500000-0000-4000-8000-000000000010'),1,'Retry never duplicates result');
select is((select count(*)::integer from public.b2c_certificate_history),1,'Retry never duplicates history');
select is((select score from public.b2c_certificate_results where student_id='17500000-0000-4000-8000-000000000010'),'6.5','Original score scale preserved');
select ok((select not marketing_allowed and marketing_selected_by is null from public.b2c_certificate_results where student_id='17500000-0000-4000-8000-000000000010'),'Not selected for marketing by default');
select throws_ok($$select public.write_b2c_certificate_result('save',current_setting('test.cert')::jsonb||'{"score":"7.0"}')$$,'22023',null,'Changed retry rejected');
select throws_ok($$select public.write_b2c_certificate_result('save',current_setting('test.cert')::jsonb||'{"request_id":"17500000-0000-4000-8000-000000000021","certificate_type":"ielts","level":"academic"}')$$,'22023',null,'Duplicate attempt detected ignoring case');
select set_config('test.result_id',(select id::text from public.b2c_certificate_results where student_id='17500000-0000-4000-8000-000000000010'),true);
select set_config('test.cert',(current_setting('test.cert')::jsonb||jsonb_build_object('request_id','17500000-0000-4000-8000-000000000022','id',current_setting('test.result_id'),'marketing_allowed',true,'marketing_note','APPROVED','expected_updated_at',(select updated_at from public.b2c_certificate_results where id=current_setting('test.result_id')::uuid)))::text,true);
