select throws_ok($$select public.write_b2c_certificate_result('save',current_setting('test.cert')::jsonb||'{"student_id":"17500000-0000-4000-8000-000000000011"}')$$,'22023',null,'Cannot move result to different student');
select lives_ok($$select public.write_b2c_certificate_result('save',current_setting('test.cert')::jsonb)$$,'Manager chooses marketing result');
select is((select marketing_selected_by from public.b2c_certificate_results where id=current_setting('test.result_id')::uuid),'17500000-0000-4000-8000-000000000001'::uuid,'Marketing selection records actual actor');
select is((select actor_id from public.b2c_certificate_history where after_data->>'marketing_allowed'='true'),'17500000-0000-4000-8000-000000000001'::uuid,'History captures actual actor');
select lives_ok($$select public.write_b2c_certificate_result('save',jsonb_build_object('request_id','17500000-0000-4000-8000-000000000023','id',null,'expected_updated_at',null,'student_id','17500000-0000-4000-8000-000000000010','certificate_type','Cambridge','level','B1 Preliminary','score','Pass','exam_date','2026-10-16','marketing_allowed',false,'marketing_note','','notes',''))$$,'Textual certificate result supported');
select is((public.read_b2c_certificate_results('{"studentId":"17500000-0000-4000-8000-000000000010"}')->>'total')::integer,2,'Student results retain separate certificates');
select is((public.read_b2c_certificate_results('{"studentId":"17500000-0000-4000-8000-000000000010"}')->>'student_count')::integer,1,'Distinct students counted without enrollment duplication');
select is((public.read_b2c_certificate_results('{"studentId":"17500000-0000-4000-8000-000000000010","marketing":"yes"}')->>'total')::integer,1,'Marketing filter selects explicit choices only');
select is((public.read_b2c_certificate_results('{"query":"TEST-CERT-STUDENT","from":"2026-10-17","to":"2026-10-17"}')->>'total')::integer,1,'Date filtering matches exam date');
select is((public.read_b2c_certificate_results('{"query":"TEST-CERT-STUDENT","certificateType":"ielts"}')->>'total')::integer,1,'Type filter case insensitive');
