select lives_ok($$select public.write_b2c_certificate_result('archive',current_setting('test.archive')::jsonb)$$,'Archive preserves historical result');
select is((public.read_b2c_certificate_results('{"studentId":"17500000-0000-4000-8000-000000000010","marketing":"yes"}')->>'total')::integer,0,'Archived results excluded from active marketing');
select is((public.read_b2c_certificate_results('{"studentId":"17500000-0000-4000-8000-000000000010","archived":true}')->>'total')::integer,1,'Archived result still readable');
select set_config('test.archive',(current_setting('test.archive')::jsonb||jsonb_build_object('request_id','17500000-0000-4000-8000-000000000025','expected_updated_at',(select updated_at from public.b2c_certificate_results where id=current_setting('test.result_id')::uuid)))::text,true);
