select set_config('request.jwt.claims','{"sub":"17500000-0000-4000-8000-000000000001","role":"authenticated"}',true);
alter table public.b2c_certificate_history add constraint test_cert_history_failure check(after_data->>'score'<>'FAIL-HISTORY') not valid;
select set_config('test.cert',(current_setting('test.cert')::jsonb||jsonb_build_object('request_id','17500000-0000-4000-8000-000000000026','score','FAIL-HISTORY','expected_updated_at',(select updated_at from public.b2c_certificate_results where id=current_setting('test.result_id')::uuid)))::text,true);
set local role authenticated;
select throws_ok($$select public.write_b2c_certificate_result('save',current_setting('test.cert')::jsonb)$$,'23514',null,'History failure rolls back result update');
select is((select score from public.b2c_certificate_results where id=current_setting('test.result_id')::uuid),'6.5','Failed history preserves prior result');
